/** user-defined events **/



/** user-defined constants **/



/** user-defined types **/

export type AppError = 
/**
 * The row asked for does not exist (deleted, or a stale id from the UI).
 */
{ type: "NotFound"; what: string; id: number } | 
/**
 * The input breaks a rule, e.g. an empty title.
 */
{ type: "Invalid"; message: string } | 
/**
 * A lookup or download failed (offline, timeout, server error).
 */
{ type: "Network"; message: string } | 
/**
 * SQLite failed. The message is for logs; the UI shows a generic error.
 */
{ type: "Database"; message: string }
/**
 * Application preferences that persist to disk.
 * Only contains settings that should be saved between sessions.
 */
export type AppPreferences = { theme: string; 
/**
 * Global shortcut for quick pane (e.g., "CommandOrControl+Shift+.")
 * If None, uses the default shortcut
 */
quick_pane_shortcut: string | null; 
/**
 * User's preferred language (e.g., "en", "es", "de")
 * If None, uses system locale detection
 */
language: string | null; 
/**
 * Look of the Todo Duo widgets. Missing in files saved before it existed.
 */
duo_style?: DuoStyle }
export type Bucket = { key: string; done: number; minutes: number }
export type Calendar = { id: number; name: string; url: string; color: string; isVisible: boolean; fetchedAt: string | null; error: string | null; eventCount: number }
export type CalendarEvent = { id: number; calendarId: number; color: string; title: string; location: string; startMs: number; endMs: number; allDay: boolean }
export type CheckIns = { 
/**
 * Days in a row (up to today) that met their line; days without a line don't break it.
 */
streak: number; yesterday: DayResult | null; shortfall: number; days: DayResult[] }
export type Conference = { key: string; title: string; description: string; area: string; ccf: string; core: string; editions: Edition[] }
export type ConferenceList = { 
/**
 * When the list was last downloaded (RFC 3339); None = never.
 */
fetchedAt: string | null; conferences: Conference[] }
export type CpuSample = { usage: number; cores: number[]; frequencyMhz: number }
/**
 * How much of one day's tasks are done: one heatmap cell.
 */
export type DayCompletion = { date: string; total: number; done: number }
export type DayItem = { kind: DayItemKind; title: string; color: string; done: boolean }
export type DayItemKind = "ProjectDeadline" | "TaskDue" | "Scheduled"
export type DayMarks = { date: string; 
/**
 * Estimated minutes of the tasks scheduled on this day.
 */
plannedMinutes: number; 
/**
 * Minutes available that day (weekday default or override); None = not set.
 */
availableMinutes: number | null; 
/**
 * Deadlines first, then scheduled tasks.
 */
items: DayItem[] }
export type DayNote = { date: string; text: string }
export type DayOverride = { date: string; minutes: number }
export type DayResult = { date: string; line: number; done: number; met: boolean }
export type Deadline = { kind: DeadlineKind; id: number; title: string; detail: string; date: string; daysLeft: number }
export type DeadlineKind = "Idea" | "Project" | "Task" | "Conference"
export type DiskIoSample = { read: number; written: number }
export type Drive = { name: string; mount: string; total: number; available: number; removable: boolean }
export type DuoFont = "system" | "serif" | "mono"
export type DuoMaterial = "translucent" | "acrylic" | "mica" | "solid"
export type DuoStyle = { material: DuoMaterial; font: DuoFont; text_size: DuoTextSize }
export type DuoTextSize = "small" | "medium" | "large"
/**
 * One year of a conference.
 */
export type Edition = { id: string; year: number; link: string; date: string; place: string; timezone: string; stages: Stage[]; 
/**
 * The project planned for this edition, if the user made one.
 */
projectId?: number | null }
export type Export = { title: string; rows: ExportRow[] }
export type ExportRow = { id: number; date: string | null; startTime: string | null; endTime: string | null; title: string; project: string | null; module: string | null; estimateMinutes: number | null; actualMinutes: number | null; dueDate: string | null; done: boolean; note: string }
export type ExportScope = { kind: "Day"; date: string } | { kind: "Week"; date: string } | { kind: "Month"; date: string } | { kind: "Project"; id: number }
export type Feed = { id: number; title: string; url: string; site: string; fetchedAt: string | null; error: string | null; unread: number }
export type FeedItem = { id: number; feedId: number; feedTitle: string; title: string; link: string; author: string; summary: string; image: string | null; dateMs: number; isRead: boolean; taskId: number | null }
export type ForecastDay = { date: string; minutes: number; capacity: number | null }
export type GpuInfo = { index: number; name: string; memoryTotal: number | null }
/**
 * A compute program on a GPU: PID, user, VRAM and run time (the command
 * is not shown, user decision 2026-11-20). The user is empty when no
 * source on the machine tells it.
 */
export type GpuProcess = { pid: number; user: string; gpuMemory: number | null; runningSecs: number | null }
export type GpuSample = { index: number; name: string; usage: number | null; memoryUsed: number | null; memoryTotal: number | null; temperature: number | null; powerWatts: number | null; powerLimitWatts: number | null; fanPercent: number | null; clockMhz: number | null; 
/**
 * Compute programs only: graphics programs (the desktop, browsers)
 * are not what a researcher looks for here.
 */
processes: GpuProcess[] }
/**
 * Ordered from best to worst, so the worst phase is the max.
 */
export type Health = "Done" | "Unestimated" | "NoDailyTime" | "OnTrack" | "Tight" | "Behind" | "Overdue"
export type Idea = { id: number; title: string; description: string; status: IdeaStatus; priority: number; isPinned: boolean; venue: string; deadline: string | null; stepCount: number; stepsDone: number; currentStep: string | null; openTodos: number; openProblems: number; logCount: number; tags: Tag[]; createdAt: string; 
/**
 * The project this idea is worked on in; its todos are that project's tasks.
 */
projectId: number | null }
/**
 * Counts for the filter chips.
 */
export type IdeaCounts = { all: number; pinned: number; unfinished: number; byStatus: ([IdeaStatus, number])[]; byTag: ([number, number])[] }
/**
 * Which ideas the list shows. All None / false = every idea.
 */
export type IdeaFilter = { status: IdeaStatus | null; pinned: boolean; unfinished: boolean; tagId: number | null }
export type IdeaLink = { id: number; ideaId: number; label: string; url: string }
export type IdeaLog = { id: number; ideaId: number; date: string; text: string }
/**
 * A paper as attached to one idea.
 */
export type IdeaPaper = { paper: Paper; relation: PaperRelation; note: string }
export type IdeaProblem = { id: number; ideaId: number; problem: string; solution: string; isSolved: boolean }
/**
 * Where an idea is, from first spark to submission.
 */
export type IdeaStatus = "Spark" | "Researching" | "InProgress" | "Writing" | "Submitted" | "Done" | "OnHold" | "Dropped"
export type IdeaStep = { id: number; ideaId: number; title: string; doneOn: string | null }
export type IdeaTodo = { id: number; ideaId: number; title: string; dueDate: string | null; done: boolean }
/**
 * Everything the idea detail can edit, sent whole on every save.
 */
export type IdeaUpdate = { title: string; description: string; status: IdeaStatus; priority: number; isPinned: boolean; venue: string; deadline: string | null; tagIds: number[] }
export type ItemStatus = "All" | "WithDeadline" | "Done"
export type JsonValue = null | boolean | number | string | JsonValue[] | Partial<{ [key in string]: JsonValue }>
export type Limit = { kind: LimitKind; name: string; date: string }
/**
 * What a piece of planned work has to be finished by, so the UI can say
 * why a day is full ("for phase Method, ending Sun, Nov 22").
 */
export type LimitKind = "Deadline" | "Phase" | "Due" | "DoOn"
export type MachineInfo = { hostName: string; os: string; cpuBrand: string; logicalCores: number; physicalCores: number | null; memoryTotal: number; gpus: GpuInfo[] }
/**
 * One machine's readings, as sent to the UI in each second's batch.
 */
export type MachineSample = { target: MonitorTarget; sample: Sample }
export type MemorySample = { used: number; total: number; swapUsed: number; swapTotal: number }
/**
 * A group of a project's tasks. With an end date it is a phase: the safety
 * line plans its tasks between the previous phase's end and its own.
 */
export type Module = { id: number; projectId: number; name: string; sortOrder: number; endDate: string | null; budgetMinutes: number | null }
/**
 * Which machine to watch: this PC, a running WSL distribution, or a host
 * named in the user's SSH config.
 */
export type MonitorTarget = { kind: "local" } | { kind: "wsl"; distro: string } | { kind: "ssh"; host: string }
export type OpenProblem = { id: number; ideaId: number; ideaTitle: string; problem: string }
export type OpenTodo = { id: number; ideaId: number; ideaTitle: string; title: string; dueDate: string | null }
export type Paper = { id: number; title: string; authors: string[]; year: number | null; venue: string; kind: string; doi: string | null; arxivId: string | null; url: string; summary: string; status: ReadingStatus; notes: string; ideaCount: number; createdAt: string }
export type PaperCounts = { all: number; byStatus: ([ReadingStatus, number])[] }
export type PaperFilter = { status: ReadingStatus | null; 
/**
 * Matches title, authors or venue.
 */
search: string | null }
/**
 * An idea a paper is attached to (shown on the paper).
 */
export type PaperIdea = { ideaId: number; title: string; relation: PaperRelation }
export type PaperRelation = "Inspiration" | "Baseline" | "Competing" | "Reference"
/**
 * Everything the paper page edits.
 */
export type PaperUpdate = { title: string; authors: string[]; year: number | null; venue: string; status: ReadingStatus; notes: string }
export type Period = "Week" | "Month" | "Year"
/**
 * One module of a new project as the dialog sends it. With an end date it
 * is a phase; the budget is typed like an estimate ("40h").
 */
export type PhaseInput = { name: string; endDate: string | null; budget: string | null }
export type PlanningSettings = { dayStart: string; level: boolean; earliestFirst: boolean }
export type Project = { id: number; name: string; color: string; template: string; startDate: string | null; deadline: string | null; bufferDays: number; planDate: string | null; isArchived: boolean; sortOrder: number; taskCount: number; doneCount: number; estimateMinutes: number; doneEstimateMinutes: number }
export type ProjectHealth = { projectId: number; ratio: number; samples: number; remaining: number; predictedRemaining: number; neededPerDay: number | null; health: Health; 
/**
 * What the part that decides the health must be finished by.
 */
limit: Limit | null }
/**
 * The project dialog's fields, sent whole on create and on every save.
 */
export type ProjectInput = { name: string; color: string; startDate: string | null; deadline: string | null; bufferDays: number; isArchived: boolean }
export type ProjectLine = { projectId: number; name: string; color: string; minutes: number; doneMinutes: number }
/**
 * The round a conference project was made for, as ccfddl has it now (it
 * may have moved the deadline since).
 */
export type ProjectRound = { title: string; edition: Edition; stage: number }
export type ProjectTemplate = { id: string; phases: TemplatePhase[] }
export type ProjectTime = { projectId: number | null; name: string | null; color: string | null; minutes: number; done: number }
export type ReadingStatus = "ToRead" | "Reading" | "Read"
/**
 * Error types for recovery operations (typed for frontend matching)
 */
export type RecoveryError = 
/**
 * File does not exist (expected case, not a failure)
 */
{ type: "FileNotFound" } | 
/**
 * Filename validation failed
 */
{ type: "ValidationError"; message: string } | 
/**
 * Data exceeds size limit
 */
{ type: "DataTooLarge"; max_bytes: number } | 
/**
 * File system read/write error
 */
{ type: "IoError"; message: string } | 
/**
 * JSON serialization/deserialization error
 */
{ type: "ParseError"; message: string }
export type ResearchOverview = { byStatus: ([IdeaStatus, number])[]; unfinished: number; openTodos: number; openProblems: number; toRead: number; active: Idea[]; deadlines: Deadline[]; todos: OpenTodo[]; problems: OpenProblem[] }
/**
 * Which round of which conference a new project is for.
 */
export type RoundRef = { key: string; editionId: string; stage: number }
export type RunningTimer = { taskId: number; title: string; startedAt: string }
/**
 * One second's readings. Network traffic and the machine's whole process
 * list are not read (2026-11-19, user decision); GPU programs are.
 */
export type Sample = { atMs: number; cpu: CpuSample; memory: MemorySample; gpus: GpuSample[]; disk: DiskIoSample; drives: Drive[]; 
/**
 * Why there are no readings: the connection failed or closed.
 */
error: string | null }
/**
 * One round of submission: an optional abstract deadline, then the paper.
 */
export type Stage = { abstractAt: number | null; deadlineAt: number | null; comment: string }
export type Stats = { from: string; to: string; done: number; minutes: number; planned: number; plannedDone: number; activeDays: number; days: number; trend: Bucket[]; projects: ProjectTime[]; weekdays: Bucket[] }
export type Tag = { id: number; name: string; color: string }
export type Task = { id: number; title: string; note: string; isImportant: boolean; isPinned: boolean; dueDate: string | null; doneAt: string | null; sortOrder: number; projectId: number | null; moduleId: number | null; estimateMinutes: number | null; actualMinutes: number | null; 
/**
 * 'YYYY-MM-DD': the day the task is planned for. "In My Day" means this is today.
 */
scheduledDate: string | null; startTime: string | null; endTime: string | null; 
/**
 * The task this one is a subtask of (one level deep), and its title.
 */
parentId: number | null; parentTitle: string | null; subtaskCount: number; subtasksDone: number; createdAt: string; 
/**
 * The idea this task is a todo of, if any.
 */
ideaId: number | null; 
/**
 * RFC 3339 UTC; set while the task is in progress ("Doing" on a board).
 */
startedAt: string | null }
/**
 * Where a task stands on a project's board.
 */
export type TaskStage = "Todo" | "Doing" | "Done"
/**
 * Everything the details pane can edit, sent whole on every save.
 */
export type TaskUpdate = { title: string; note: string; isImportant: boolean; isPinned: boolean; scheduledDate: string | null; dueDate: string | null; estimate: string | null }
/**
 * The built-in lists in the sidebar.
 */
export type TaskView = "MyDay" | "Important" | "Tasks"
export type TemplatePhase = { name: string; daysBefore: number | null }
export type TodayLine = { date: string; minutes: number; doneMinutes: number; capacity: number | null; projects: ProjectLine[] }
/**
 * Minutes per weekday, Monday first; None = no limit.
 */
export type WeekCapacity = [(number | null), (number | null), (number | null), (number | null), (number | null), (number | null), (number | null)]

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
